function openReviewTask(out, state, id) {
  state.humanTasks ??= [];
  if (state.humanTasks.includes(id)) return;
  state.humanTasks.push(id);
  out.humanTasks.push({
    id,
    kind: 'fraudReview',
    role: 'fraudAnalyst',
    subject: state.orderId,
    question: `Review fraud check for order ${state.orderId}: approve or reject?`,
    answerSchema: {
      type: 'object',
      required: ['decision'],
