}

// Handled on the tick where an effect result arrives for this order.
function handleAllocResult(r, ctx, out, state) {
  const fulfilments = findKey(r, 'fulfilments') ?? [];
  const plan = { fulfilments };
  const edition = pickEdition(ctx, state.placedAt);
  const amounts = computeAmounts(ctx, edition, state.items, { fulfilments });
  state.edition = edition?.id ?? null;
  state.fulfilments = amounts.fulfilments.map((f) => {
    const planned = fulfilments.find((p) => p.fulfilmentId === f.fulfilmentId);
    return { ...f, available: f.location != null && planned?.available !== false };
  });
  state.totalMinor = amounts.totalMinor;
  state.stage = 'recording';
  out.effects.push({
    key: `order:${state.orderId}`,
    system: 'orders',
    op: 'create',
    args: {
      orderId: state.orderId,
      customerId: state.customerId,
      placedAt: state.placedAt,
      currency: state.currency,
      items: state.items,
      fulfilments: amounts.fulfilments,
      totalMinor: state.totalMinor,
    },
  });
