function ms(iso) {
  return Date.parse(iso);
}

function addMin(iso, minutes) {
  return new Date(ms(iso) + minutes * MIN).toISOString();
}

function parseJsonFile(ctx, path) {
  const f = ctx.files?.[path] ?? ctx.files?.get?.(path);
  if (f == null) return null;
  if (typeof f === 'string') return JSON.parse(f);
  return f;
}

