    emit(out, state, {
      key: `rel:${state.orderId}:${f.fulfilmentId}:${sku}`,
      system: 'inventory',
      op: 'release',
      args: { orderId: state.orderId, fulfilmentId: f.fulfilmentId, sku },
    });
