    setStatus(out, state, f.fulfilmentId, 'dispatched');
    setStatus(out, state, f.fulfilmentId, 'completed');
    checkOrderOutcome(out, state);
  } else if (meaning === 'collectionFailed') {
    f.collectionFailed = true;
    failFulfilment(out, state, f);
  }
}

