238	    key: `order:${state.orderId}`,
239	    system: 'orders',
240	    op: 'create',
241	    args: {
242	      orderId: state.orderId,
243	      customerId: state.customerId,
244	      placedAt: state.placedAt,
245	      currency: state.currency,
246	      items: state.items,
247	      fulfilments: state.fulfilments.map((f) => ({
248	        fulfilmentId: f.fulfilmentId, location: f.location, items: f.items, amountMinor: f.amountMinor,
249	      })),
250	      totalMinor: state.totalMinor,
251	    },
252	  });
