256	// ---------- R2 fraud decision ----------
257	
258	function handleFraudVerdict(verdict, ctx, out, state, now) {
259	  if (verdict === 'pass') {
260	    onCleared(out, state, state.placedAt);
261	  } else if (verdict === 'reject') {
262	    cancelOrder(out, state, 'fraud');
263	  } else if (verdict === 'review') {
