377	// R4.2.1: one batch per fulfilment; items keep their original keys across resubmissions.
378	function reserveItems(out, state, f, attempt, items) {
379	  f.reserveAttempt = attempt;
380	  emit(out, state, {
381	    system: 'inventory',
382	    op: 'reserve',
383	    args: {
384	      orderId: state.orderId,
385	      fulfilmentId: f.fulfilmentId,
386	      location: f.location,
387	      items: items.map((it) => ({ key: itemKey(state, f, it.sku), sku: it.sku, qty: it.qty })),
