402	    }
403	  }
404	  const failed = outcomes.filter((o) => o.status !== 'ok' && o.ok !== true);
405	  if (r.status === 'partial' && failed.length > 0) {
406	    const retry = f.items.filter((it) => failed.some((o) => o.key === itemKey(state, f, it.sku)));
