455	  }
456	  if (f.charged) {
457	    emit(out, state, {
458	      key: `ref:${state.orderId}:${f.fulfilmentId}`,
459	      system: 'billing',
460	      op: 'refund',
461	      args: { orderId: state.orderId, fulfilmentId: f.fulfilmentId, amountMinor: f.amountMinor },
462	    });
463	  }
464	  for (const sku of f.reservedSkus ?? []) {
465	    emit(out, state, {
466	      key: `rel:${state.orderId}:${f.fulfilmentId}:${sku}`,
