492	  if (!state.fulfilments.every((f) => TERMINAL.includes(f.status))) return;
493	  const statuses = state.fulfilments.map((f) => f.status);
494	  const outcome = statuses.includes('completed') ? 'completed' : statuses.includes('failed') ? 'failed' : 'cancelled';
495	  state.finalStatus = outcome;
496	  setStatus(out, state, null, outcome);
497	}
