499	// ---------- saga results (R4.2 steps, with R5 on failure) ----------
500	
501	// A step that commits after the order was stopped is compensated at once (R6.2); nothing new is started.
502	function handleAfterStop(r, out, state, kind, f) {
503	  if (r.status !== 'ok' && r.status !== 'partial') return;
504	  if (kind === 'res') {
505	    f.reservedSkus ??= [];
506	    for (const o of batchItems(r)) {
507	      const sku = o.sku ?? String(o.key ?? '').split(':').pop();
508	      if (o.status === 'ok' && !f.reservedSkus.includes(sku)) f.reservedSkus.push(sku);
509	    }
510	  } else if (kind === 'chg' && r.status === 'ok') {
511	    f.charged = true;
512	  } else if (kind === 'ship' && r.status === 'ok') {
513	    f.shipped = true;
514	  } else {
515	    return;
516	  }
517	  compensate(out, state, f);
518	}
519	
520	// Routes one effect result to the saga step it belongs to. Returns true when it was handled.
521	function handleSagaResult(r, out, state) {
522	  // A reserve batch has no key of its own; its items carry keys that name the fulfilment.
523	  const idSource = r.op === 'reserve' ? batchItems(r).find((o) => String(o.key ?? '').startsWith('rsv:'))?.key : r.key;
524	  const parts = String(idSource ?? '').split(':');
525	  if (parts.length < 3 || parts[1] !== state.orderId) return false;
526	  const kind = r.op === 'reserve' ? 'res' : parts[0];
527	  const f = fulfilmentOf(state, parts[2]);
528	  if (!f) return false;
529	  if (state.stopped) {
530	    handleAfterStop(r, out, state, kind, f);
531	    return true;
532	  }
533	  if (TERMINAL.includes(f.status)) return false;
534	
535	  if (kind === 'res' && (r.status === 'ok' || r.status === 'partial')) {
536	    handleReserveResult(r, out, state, f);
537	    return true;
538	  }
539	  if (kind === 'res' && r.status === 'error') {
540	    const e = errOf(r);
541	    if ((e.permanent && !e.invalidArgs && !e.fieldRenamed) || f.reserveAttempt >= 5) {
542	      failFulfilment(out, state, f);
543	    } else {
544	      // Items already reserved keep their keys; resubmit only the rest.
545	      const rest = f.items.filter((it) => !(f.reservedSkus ?? []).includes(it.sku));
546	      reserveItems(out, state, f, f.reserveAttempt + 1, rest);
547	    }
548	    return true;
549	  }
550	  if (kind === 'chg') {
551	    const e = errOf(r);
552	    if (r.status === 'ok') {
553	      f.charged = true;
554	      shipFulfilment(out, state, f);
555	    } else if ((e.fieldRenamed || e.invalidArgs) && (f.chargeReissues ?? 0) < 3) {
556	      f.chargeReissues = (f.chargeReissues ?? 0) + 1;
557	      chargeFulfilment(out, state, f, true);
558	    } else if (e.cardDeclined || e.permanent) {
559	      failFulfilment(out, state, f);
560	    }
561	    return true;
562	  }
563	  if (kind === 'ship') {
564	    if (r.status === 'ok') {
565	      f.shipped = true;
566	    } else if (errOf(r).permanent && !errOf(r).invalidArgs) {
567	      failFulfilment(out, state, f);
568	    }
569	    return true;
570	  }
571	  return false;
572	}
