574	// ---------- R4.4 carrier messages ----------
575	
576	function carrierMeaning(ctx, edition, code) {
577	  const table = rulebookTable(ctx, edition, 'carrier-codes.json');
578	  const rows = Array.isArray(table) ? table : table ? Object.entries(table).map(([c, v]) => ({ code: c, meaning: typeof v === 'string' ? v : v.meaning })) : [];
579	  return rows.find((r) => r.code === code)?.meaning ?? 'info';
580	}
