582	function handleCarrier(ev, ctx, out, state) {
583	  const p = ev.payload;
584	  const f = fulfilmentOf(state, p.fulfilmentRef);
585	  if (!f || TERMINAL.includes(f.status)) return;
586	  const edition = pickEdition(ctx, state.placedAt);
587	  const meaning = carrierMeaning(ctx, edition, p.code);
588	  if (meaning === 'collected' || meaning === 'inTransit' || meaning === 'delivered') {
589	    // S7: any of these proves collection, judged by reportedAt; the earliest proof counts.
590	    const at = p.reportedAt ?? ev.at;
591	    if (state.collectedAt == null || Date.parse(at) < Date.parse(state.collectedAt)) state.collectedAt = at;
592	  }
593	  if (meaning === 'collected') {
594	    setStatus(out, state, f.fulfilmentId, 'dispatched');
595	  } else if (meaning === 'delivered') {
