605	// ---------- customer actions (R3.2, R6.2-R6.4) ----------
606	
607	function handleCustomerAction(ev, out, state) {
608	  const p = ev.payload;
609	  if (normaliseOrderId(p.orderRef) !== state.orderId) return;
610	  if (state.finalStatus || state.cancelRequested) return;
611	  const a = ev.at;
612	
613	  if (state.waiting) {
614	    // R3.2: the first amend or cancel at or before D counts; later ones change nothing.
615	    if (Date.parse(a) > Date.parse(state.D)) return;
616	    state.waiting = false;
617	    if (p.action === 'cancel') {
618	      cancelOrder(out, state, 'customer');
619	      return;
620	    }
621	    if (p.action === 'amend') {
622	      for (const f of state.fulfilments) {
623	        if (!f.available) setStatus(out, state, f.fulfilmentId, 'cancelled');
624	      }
625	      if (state.fulfilments.some((f) => f.available)) startProcessing(out, state, a);
626	      else cancelOrder(out, state, 'nothing-available');
