628	    return;
629	  }
630	
631	  if (p.action !== 'cancel') return;
632	  if (state.ready) {
633	    // R6.2 / S4 / S7: a collection reported at or before the cancel wins.
634	    if (state.collectedAt != null && Date.parse(state.collectedAt) <= Date.parse(a)) {
635	      notify(out, state, 'cancel-refused', state.orderId);
636	      return;
637	    }
638	    cancelOrder(out, state, 'customer');
639	    return;
640	  }
641	  if (state.cleared == null) cancelOrder(out, state, 'customer'); // R6.4: fraud review still open
642	}
