690	          if (state.stage === 'await-allocation' && r.key === `alloc:${state.orderId}`) {
691	            handleAllocResult(r, ctx, out, state);
692	          } else if (state.orderId && r.key === `fraud:${state.orderId}` && state.stage === 'recording') {
693	            state.stage = 'checked';
694	            handleFraudVerdict(findKey(r, 'verdict'), ctx, out, state, now);
695	          } else if (state.orderId) {
696	            handleSagaResult(r, out, state);
697	          }
698	        } else if (ev.type === 'timer.fired' && state.orderId) {
699	          handleTimer(findKey(ev, 'onDue'), out, state);
700	        } else if (ev.type?.startsWith('humanTask.') && state.orderId) {
701	          if (ev.type === 'humanTask.answered') handleReviewAnswer(ev, out, state);
702	          else if (ev.type === 'humanTask.answerRejected' || ev.type === 'humanTask.withdrawn') askReviewAgain(out, state, ev.at);
703	        } else if (ev.source === 'shop' && ev.payload?.orderId != null) {
704	          handlePlaced(ev, input, ctx, out, state);
705	        } else if (ev.source === 'customer-portal' && ev.payload?.orderRef != null) {
706	          if (state.orderId) handleCustomerAction(ev, out, state);
707	          else routeToOrder(normaliseOrderId(ev.payload.orderRef), input, ctx, out);
708	        } else if (ev.source === 'carrier') {
709	          if (state.orderId) handleCarrier(ev, ctx, out, state);
710	          else routeCarrier(ev, input, ctx, out);
711	        }
712	      }
713	      // Effects are written against the live API schemas (renames included).
714	      out.effects = out.effects.map((e) => ({ ...e, args: conformArgs(ctx, e.system, e.op, e.args) }));
715	      out.decisions.subject = state.orderId ?? null;
716	      out.carry = state;
717	      return out;
718	    },
719	  };
720	}
721	
722	// Effect results carry { key, system, op, status, items?, error? }, either on the event or under its payload.
723	// Returns that result object, or null when the event is not an effect result.
724	function resultOf(ev) {
725	  if (ev.type !== 'effect.result') return null;
726	  const p = ev.payload ?? {};
727	  return { ...ev, ...p, key: p.key ?? ev.key };
728	}
