  'rulebook/ed1/policy.json': { customerActionHours: 24, fraudReviewHours: 4, collectionCutoffMinutes: 60 },
  'rulebook/ed1/shipping-fees.json': [{ location: 'AMS', feeMinor: 500 }, { location: 'RTM', feeMinor: 300 }],
  'rulebook/ed1/carrier-codes.json': { C1: 'collected', C2: 'inTransit', C3: 'delivered', C4: 'collectionFailed' },
  'master/catalog.json': [{ sku: 'A', unitPriceMinor: 1000 }, { sku: 'B', unitPriceMinor: 250 }],
  'master/customers.json': [{ id: 'CUST-1', email: 'c1@example.test' }],
  'api/billing.schema.json': { ops: { charge: { args: { properties: { amountMinor: {} } } } } },
};

const solver = createSolver();
const ctx = { files, instances: () => [], query: () => [], status: () => 'not-found' };

let n = 0;
function ev(type, at, extra = {}) {
  n += 1;
  return { id: `e${n}`, type, at, source: extra.source ?? 'x', channel: { kind: 'instance', instance: 'i-1' }, payload: extra.payload ?? {}, key: extra.key };
}
// Runs one case-tick and keeps the carry for the next one.
let carry = null;
function tick(now, events) {
  const out = solver.tick({ kind: 'case', item: 'x', world: 'w', instance: 'i-1', now, events, carry }, ctx);
  carry = JSON.parse(JSON.stringify(out.carry));
  return out;
}
const effOps = (out) => out.effects.map((e) => `${e.system}.${e.op}`);
const statusSets = (out) => out.effects.filter((e) => e.op === 'setStatus').map((e) => `${e.args.fulfilmentId ?? 'order'}=${e.args.status}`);

