    const byName = unmatchedProps.find((p) => norm(p) === norm(k));
    const byType = unmatchedArgs.length === 1 && unmatchedProps.length === 1 ? unmatchedProps[0] : undefined;
    out[byName ?? byType ?? k] = args[k];
