// ---------- R1 amounts ----------

function catalogPrices(ctx) {
  const catalog = parseJsonFile(ctx, 'master/catalog.json');
  const rows = Array.isArray(catalog) ? catalog : catalog?.items ?? catalog?.products ?? [];
  const price = new Map();
  if (Array.isArray(rows)) {
