    id,
    kind: 'fraudReview',
    role: 'fraudAnalyst',
    subject: state.orderId,
    question: `Review fraud check for order ${state.orderId}: approve or reject?`,
    answerSchema: {
      type: 'object',
      required: ['decision'],
      properties: { decision: { enum: ['approve', 'reject'] } },
