// Local rule checks for solver.mjs with a fake ctx and synthetic events. Run: node test/rules.test.mjs
import assert from 'node:assert/strict';
import { createSolver } from '../solver.mjs';

const files = {
  'rulebook/ed1/edition.json': { id: 'ed1', effectiveFrom: '2026-01-01' },
  'rulebook/ed1/policy.json': { customerActionHours: 24, fraudReviewHours: 4, collectionCutoffMinutes: 60 },
  'rulebook/ed1/shipping-fees.json': [{ location: 'AMS', feeMinor: 500 }, { location: 'RTM', feeMinor: 300 }],
  'rulebook/ed1/carrier-codes.json': { C1: 'collected', C2: 'inTransit', C3: 'delivered', C4: 'collectionFailed' },
  'master/catalog.json': [{ sku: 'A', unitPriceMinor: 1000 }, { sku: 'B', unitPriceMinor: 250 }],
  'master/customers.json': [{ id: 'CUST-1', email: 'c1@example.test' }],
  'api/billing.schema.json': { ops: { charge: { args: { properties: { amountMinor: {} } } } } },
};

const solver = createSolver();
const ctx = { files, instances: () => [], query: () => [], status: () => 'not-found' };

let n = 0;
function ev(type, at, extra = {}) {
  n += 1;
  return { id: `e${n}`, type, at, source: extra.source ?? 'x', channel: { kind: 'instance', instance: 'i-1' }, payload: extra.payload ?? {}, key: extra.key };
}
// Runs one case-tick and keeps the carry for the next one.
let carry = null;
function tick(now, events) {
  const out = solver.tick({ kind: 'case', item: 'x', world: 'w', instance: 'i-1', now, events, carry }, ctx);
  carry = JSON.parse(JSON.stringify(out.carry));
  return out;
}
const effOps = (out) => out.effects.map((e) => `${e.system}.${e.op}`);
const statusSets = (out) => out.effects.filter((e) => e.op === 'setStatus').map((e) => `${e.args.fulfilmentId ?? 'order'}=${e.args.status}`);

const P = '2026-10-14T10:00:00+02:00';
const placed = (orderId, items) => ev('message.received', P, { source: 'shop', payload: { orderId, customerId: 'CUST-1', placedAt: P, currency: 'EUR', items, channel: 'web' } });
const allocRes = (plan) => ev('effect.result', '2026-10-14T10:02:00+02:00', { key: 'alloc:ORD-1', payload: { key: 'alloc:ORD-1', system: 'inventory', op: 'allocate', status: 'ok', items: { orderId: 'ORD-1', fulfilments: plan } } });
const fraudRes = (verdict, at) => ev('effect.result', at, { payload: { key: 'fraud:ORD-1', system: 'fraud', op: 'check', status: 'ok', items: { orderId: 'ORD-1', verdict } } });
const okRes = (key, system, op, at, extra = {}) => ev('effect.result', at, { payload: { key, system, op, status: 'ok', ...extra } });

// 1. Intake, pass, all available: amounts, create, processing statuses, reservations.
{
  const plan = [{ fulfilmentId: 'F1', location: 'AMS', available: true, items: [{ sku: 'A', qty: 2 }] }];
  let out = tick(P, [placed('  #ord-1', [{ sku: 'A', qty: 2 }])]);
  assert.deepEqual(effOps(out), ['inventory.allocate']);
  assert.equal(out.decisions.subject, 'ORD-1');
  out = tick('2026-10-14T10:02:00+02:00', [allocRes(plan)]);
  const create = out.effects.find((e) => e.op === 'create');
  assert.equal(create.args.totalMinor, 2 * 1000 + 500);
  assert.equal(create.args.fulfilments[0].amountMinor, 2500);
  out = tick('2026-10-14T10:03:00+02:00', [fraudRes('pass', '2026-10-14T10:03:00+02:00')]);
  assert.deepEqual(statusSets(out), ['order=processing', 'F1=processing']);
  assert.ok(effOps(out).includes('inventory.reserve'));
  console.log('ok 1 intake + pass');
}

// 2. Unavailable item: action-required, deadline timer at D+1min, amend before D starts processing the rest.
n = 0; carry = null;
{
  const plan = [
    { fulfilmentId: 'F1', location: 'AMS', available: true, items: [{ sku: 'A', qty: 1 }] },
    { fulfilmentId: 'F2', location: null, available: false, items: [{ sku: 'B', qty: 1 }] },
  ];
  tick(P, [placed('ORD-2', [{ sku: 'A', qty: 1 }, { sku: 'B', qty: 1 }])]);
  let out = tick('2026-10-14T10:02:00+02:00', [{ ...allocRes(plan), payload: { key: 'alloc:ORD-2', system: 'inventory', op: 'allocate', status: 'ok', items: { orderId: 'ORD-2', fulfilments: plan } } }]);
  out = tick('2026-10-14T10:03:00+02:00', [{ ...fraudRes('pass', '2026-10-14T10:03:00+02:00'), payload: { key: 'fraud:ORD-2', system: 'fraud', op: 'check', status: 'ok', items: { verdict: 'pass' } } }]);
  assert.ok(statusSets(out).includes('order=customerActionRequired'));
  assert.ok(out.effects.some((e) => e.op === 'send' && e.args.template === 'action-required'));
  const timer = out.obligations.upsert.find((o) => o.onDue === 'customerDeadline');
  assert.equal(timer.dueAt, new Date(Date.parse(P) + 24 * 3600e3 + 60e3).toISOString());
  // amend at 12:00 (before D): F2 cancelled, F1 keeps going
  out = tick('2026-10-14T12:00:00+02:00', [ev('message.received', '2026-10-14T12:00:00+02:00', { source: 'customer-portal', payload: { orderRef: 'ord-2', action: 'amend', from: 'c' } })]);
  assert.ok(statusSets(out).includes('F2=cancelled'));
  assert.ok(statusSets(out).includes('order=processing'));
  // later cancel is judged as processing: counts (nothing collected)
  out = tick('2026-10-14T12:05:00+02:00', [ev('message.received', '2026-10-14T12:05:00+02:00', { source: 'customer-portal', payload: { orderRef: 'ORD-2', action: 'cancel', from: 'c' } })]);
  assert.ok(out.effects.some((e) => e.op === 'cancel' || e.op === 'release' || e.op === 'setStatus'));
  assert.ok(statusSets(out).includes('order=cancelled'));
  console.log('ok 2 amend then cancel while processing');
}

// 3. Unavailable item, no action: timer fires at D+1min, order timedOut.
n = 0; carry = null;
{
  const plan = [
    { fulfilmentId: 'F1', location: 'AMS', available: true, items: [{ sku: 'A', qty: 1 }] },
    { fulfilmentId: 'F2', location: null, available: false, items: [{ sku: 'B', qty: 1 }] },
  ];
  tick(P, [placed('ORD-3', [{ sku: 'A', qty: 1 }, { sku: 'B', qty: 1 }])]);
  tick('2026-10-14T10:02:00+02:00', [{ ...allocRes(plan), payload: { key: 'alloc:ORD-3', system: 'inventory', op: 'allocate', status: 'ok', items: { orderId: 'ORD-3', fulfilments: plan } } }]);
  tick('2026-10-14T10:03:00+02:00', [{ ...fraudRes('pass', '2026-10-14T10:03:00+02:00'), payload: { key: 'fraud:ORD-3', system: 'fraud', op: 'check', status: 'ok', items: { verdict: 'pass' } } }]);
  // A late amend after D changes nothing.
  let out = tick('2026-10-15T10:01:00+02:00', [{ type: 'timer.fired', at: '2026-10-15T10:01:00+02:00', payload: { obligationId: 'x', onDue: 'customerDeadline' } }]);
  assert.ok(statusSets(out).includes('order=timedOut'));
  assert.ok(out.effects.some((e) => e.args?.template === 'order-timed-out'));
  console.log('ok 3 timeout');
}

// 4. Fraud review: timeout at deadline+1min cancels the order with no later effect from an answer.
n = 0; carry = null;
{
  const plan = [{ fulfilmentId: 'F1', location: 'AMS', available: true, items: [{ sku: 'A', qty: 1 }] }];
  tick(P, [placed('ORD-4', [{ sku: 'A', qty: 1 }])]);
  tick('2026-10-14T10:02:00+02:00', [{ ...allocRes(plan), payload: { key: 'alloc:ORD-4', system: 'inventory', op: 'allocate', status: 'ok', items: { orderId: 'ORD-4', fulfilments: plan } } }]);
  let out = tick('2026-10-14T10:03:00+02:00', [{ ...fraudRes('review', '2026-10-14T10:03:00+02:00'), payload: { key: 'fraud:ORD-4', system: 'fraud', op: 'check', status: 'ok', items: { verdict: 'review' } } }]);
  assert.equal(out.humanTasks.length, 1);
  assert.equal(out.humanTasks[0].dueAt, '2026-10-14T12:03:00.000Z'); // 10:03+02:00 plus 4 review hours
  out = tick('2026-10-14T14:04:00+02:00', [{ type: 'timer.fired', at: '2026-10-14T14:04:00+02:00', payload: { onDue: 'reviewDeadline' } }]);
  assert.ok(statusSets(out).includes('order=cancelled'));
  // An approval after the timeout changes nothing.
  out = tick('2026-10-14T14:05:00+02:00', [ev('humanTask.answered', '2026-10-14T14:05:00+02:00', { payload: { decision: 'approve' } })]);
  assert.equal(out.effects.length, 0);
  console.log('ok 4 review timeout');
}

// 5. A customer cancel during processing after a collection report is refused, nothing else changes.
n = 0; carry = null;
{
  const plan = [{ fulfilmentId: 'F1', location: 'AMS', available: true, items: [{ sku: 'A', qty: 1 }] }];
  tick(P, [placed('ORD-5', [{ sku: 'A', qty: 1 }])]);
  tick('2026-10-14T10:02:00+02:00', [{ ...allocRes(plan), payload: { key: 'alloc:ORD-5', system: 'inventory', op: 'allocate', status: 'ok', items: { orderId: 'ORD-5', fulfilments: plan } } }]);
  tick('2026-10-14T10:03:00+02:00', [{ ...fraudRes('pass', '2026-10-14T10:03:00+02:00'), payload: { key: 'fraud:ORD-5', system: 'fraud', op: 'check', status: 'ok', items: { verdict: 'pass' } } }]);
  let out = tick('2026-10-14T11:00:00+02:00', [ev('message.received', '2026-10-14T11:00:00+02:00', { source: 'carrier', payload: { carrier: 'X', code: 'C1', shipmentId: 'S', fulfilmentRef: 'F1', reportedAt: '2026-10-14T10:55:00+02:00' } })]);
  out = tick('2026-10-14T11:05:00+02:00', [ev('message.received', '2026-10-14T11:05:00+02:00', { source: 'customer-portal', payload: { orderRef: 'ORD-5', action: 'cancel', from: 'c' } })]);
  assert.ok(out.effects.some((e) => e.args?.template === 'cancel-refused'));
  assert.ok(!statusSets(out).includes('order=cancelled'));
  console.log('ok 5 cancel refused after collection');
}

console.log('all rule checks passed');
